   314  CheckedError Parser::Next() {
   315    doc_comment_.clear();
   316    bool seen_newline = cursor_ == source_;
   317    attribute_.clear();
   318    attr_is_trivial_ascii_string_ = true;
   319    for (;;) {
   320      char c = *cursor_++;
   321      token_ = c;
   322      switch (c) {
   323        case '\0':
   324          cursor_--;
   325          token_ = kTokenEof;
   326          return NoError();
   327        case ' ':
   328        case '\r':
   329        case '\t': break;
   330        case '\n':
   331          MarkNewLine();
   332          seen_newline = true;
   333          break;
   334        case '{':
   335        case '}':
   336        case '(':
   337        case ')':
   338        case '[':
   339        case ']':
   340        case ',':
   341        case ':':
   342        case ';':
   343        case '=': return NoError();
   344        case '\"':
   345        case '\'': {
   346          int unicode_high_surrogate = -1;
   347
   348          while (*cursor_ != c) {
   349            if (*cursor_ < ' ' && static_cast<signed char>(*cursor_) >= 0)
   350              return Error("illegal character in string constant");
   351            if (*cursor_ == '\\') {
   352              attr_is_trivial_ascii_string_ = false;  // has escape sequence
   353              cursor_++;
   354              if (unicode_high_surrogate != -1 && *cursor_ != 'u') {
   355                return Error(
   356                    "illegal Unicode sequence (unpaired high surrogate)");
   357              }
   358              switch (*cursor_) {
   359                case 'n':
   360                  attribute_ += '\n';
   361                  cursor_++;
   362                  break;
   363                case 't':
   364                  attribute_ += '\t';
   365                  cursor_++;
   366                  break;
   367                case 'r':
   368                  attribute_ += '\r';
   369                  cursor_++;
   370                  break;
   371                case 'b':
   372                  attribute_ += '\b';
   373                  cursor_++;
   374                  break;
   375                case 'f':
   376                  attribute_ += '\f';
   377                  cursor_++;
   378                  break;
   379                case '\"':
   380                  attribute_ += '\"';
   381                  cursor_++;
   382                  break;
   383                case '\'':
   384                  attribute_ += '\'';
   385                  cursor_++;
   386                  break;
   387                case '\\':
   388                  attribute_ += '\\';
   389                  cursor_++;
   390                  break;
   391                case '/':
   392                  attribute_ += '/';
   393                  cursor_++;
   394                  break;
   395                case 'x': {  // Not in the JSON standard
   396                  cursor_++;
   397                  uint64_t val;
   398                  ECHECK(ParseHexNum(2, &val));
   399                  attribute_ += static_cast<char>(val);
   400                  break;
   401                }
   402                case 'u': {
   403                  cursor_++;
   404                  uint64_t val;
   405                  ECHECK(ParseHexNum(4, &val));
   406                  if (val >= 0xD800 && val <= 0xDBFF) {
   407                    if (unicode_high_surrogate != -1) {
   408                      return Error(
   409                          "illegal Unicode sequence (multiple high surrogates)");
   410                    } else {
   411                      unicode_high_surrogate = static_cast<int>(val);
   412                    }
   413                  } else if (val >= 0xDC00 && val <= 0xDFFF) {
   414                    if (unicode_high_surrogate == -1) {
   415                      return Error(
   416                          "illegal Unicode sequence (unpaired low surrogate)");
   417                    } else {
   418                      int code_point = 0x10000 +
   419                                       ((unicode_high_surrogate & 0x03FF) << 10) +
   420                                       (val & 0x03FF);
   421                      ToUTF8(code_point, &attribute_);
   422                      unicode_high_surrogate = -1;
   423                    }
   424                  } else {
   425                    if (unicode_high_surrogate != -1) {
   426                      return Error(
   427                          "illegal Unicode sequence (unpaired high surrogate)");
   428                    }
   429                    ToUTF8(static_cast<int>(val), &attribute_);
   430                  }
   431                  break;
   432                }
   433                default: return Error("unknown escape code in string constant");
   434              }
   435            } else {  // printable chars + UTF-8 bytes
   436              if (unicode_high_surrogate != -1) {
   437                return Error(
   438                    "illegal Unicode sequence (unpaired high surrogate)");
   439              }
   440              // reset if non-printable
   441              attr_is_trivial_ascii_string_ &=
   442                  check_ascii_range(*cursor_, ' ', '~');
   443
   444              attribute_ += *cursor_++;
   445            }
   446          }
   447          if (unicode_high_surrogate != -1) {
   448            return Error("illegal Unicode sequence (unpaired high surrogate)");
   449          }
   450          cursor_++;
   451          if (!attr_is_trivial_ascii_string_ && !opts.allow_non_utf8 &&
   452              !ValidateUTF8(attribute_)) {
   453            return Error("illegal UTF-8 sequence");
   454          }
   455          token_ = kTokenStringConstant;
   456          return NoError();
   457        }
   458        case '/':
   459          if (*cursor_ == '/') {
   460            const char *start = ++cursor_;
   461            while (*cursor_ && *cursor_ != '\n' && *cursor_ != '\r') cursor_++;
   462            if (*start == '/') {  // documentation comment
   463              if (!seen_newline)
   464                return Error(
   465                    "a documentation comment should be on a line on its own");
   466              doc_comment_.push_back(std::string(start + 1, cursor_));
   467            }
   468            break;
   469          } else if (*cursor_ == '*') {
   470            cursor_++;
   471            // TODO: make nested.
   472            while (*cursor_ != '*' || cursor_[1] != '/') {
   473              if (*cursor_ == '\n') MarkNewLine();
   474              if (!*cursor_) return Error("end of file in comment");
   475              cursor_++;
   476            }
   477            cursor_ += 2;
   478            break;
   479          }
   480          FLATBUFFERS_FALLTHROUGH();  // else fall thru
   481        default:
   482          if (IsIdentifierStart(c)) {
   483            // Collect all chars of an identifier:
   484            const char *start = cursor_ - 1;
   485            while (IsIdentifierStart(*cursor_) || is_digit(*cursor_)) cursor_++;
   486            attribute_.append(start, cursor_);
   487            token_ = kTokenIdentifier;
   488            return NoError();
   489          }
   490
   491          const auto has_sign = (c == '+') || (c == '-');
   492          if (has_sign) {
   493            // Check for +/-inf which is considered a float constant.
   494            if (strncmp(cursor_, "inf", 3) == 0 &&
   495                !(IsIdentifierStart(cursor_[4]) || is_digit(cursor_[4]))) {
   496              attribute_.assign(cursor_ - 1, cursor_ + 3);
   497              token_ = kTokenFloatConstant;
   498              cursor_ += 3;
   499              return NoError();
   500            }
   501
   502            if (IsIdentifierStart(*cursor_)) {
   503              // '-'/'+' and following identifier - it could be a predefined
   504              // constant. Return the sign in token_, see ParseSingleValue.
   505              return NoError();
   506            }
   507          }
   508
   509          auto dot_lvl =
   510              (c == '.') ? 0 : 1;  // dot_lvl==0 <=> exactly one '.' seen
   511          if (!dot_lvl && !is_digit(*cursor_)) return NoError();  // enum?
   512          // Parser accepts hexadecimal-floating-literal (see C++ 5.13.4).
   513          if (is_digit(c) || has_sign || !dot_lvl) {
   514            const auto start = cursor_ - 1;
   515            auto start_digits = !is_digit(c) ? cursor_ : cursor_ - 1;
   516            if (!is_digit(c) && is_digit(*cursor_)) {
   517              start_digits = cursor_;  // see digit in cursor_ position
   518              c = *cursor_++;
   519            }
   520            // hex-float can't begind with '.'
   521            auto use_hex = dot_lvl && (c == '0') && is_alpha_char(*cursor_, 'X');
   522            if (use_hex) start_digits = ++cursor_;  // '0x' is the prefix, skip it
   523            // Read an integer number or mantisa of float-point number.
   524            do {
   525              if (use_hex) {
   526                while (is_xdigit(*cursor_)) cursor_++;
   527              } else {
   528                while (is_digit(*cursor_)) cursor_++;
   529              }
   530            } while ((*cursor_ == '.') && (++cursor_) && (--dot_lvl >= 0));
   531            // Exponent of float-point number.
   532            if ((dot_lvl >= 0) && (cursor_ > start_digits)) {
   533              // The exponent suffix of hexadecimal float number is mandatory.
   534              if (use_hex && !dot_lvl) start_digits = cursor_;
   535              if ((use_hex && is_alpha_char(*cursor_, 'P')) ||
   536                  is_alpha_char(*cursor_, 'E')) {
   537                dot_lvl = 0;  // Emulate dot to signal about float-point number.
   538                cursor_++;
   539                if (*cursor_ == '+' || *cursor_ == '-') cursor_++;
   540                start_digits = cursor_;  // the exponent-part has to have digits
   541                // Exponent is decimal integer number
   542                while (is_digit(*cursor_)) cursor_++;
   543                if (*cursor_ == '.') {
   544                  cursor_++;  // If see a dot treat it as part of invalid number.
   545                  dot_lvl = -1;  // Fall thru to Error().
   546                }
   547              }
   548            }
   549            // Finalize.
   550            if ((dot_lvl >= 0) && (cursor_ > start_digits)) {
   551              attribute_.append(start, cursor_);
   552              token_ = dot_lvl ? kTokenIntegerConstant : kTokenFloatConstant;
   553              return NoError();
   554            } else {
   555              return Error("invalid number: " + std::string(start, cursor_));
   556            }
   557          }
   558          std::string ch;
   559          ch = c;
   560          if (false == check_ascii_range(c, ' ', '~'))
   561            ch = "code: " + NumToString(c);
   562          return Error("illegal character: " + ch);
   563      }
   564    }
